import{Fr as e,Ir as t}from"./index-CYDk_CKL.js";var n={"qb-bell":{id:`qb-bell`,title:`The Bell That Doesn't Ring`,giver:`Sister Yuki`,bandMin:20,bandMax:45,weight:8,fateShards:1,award:`Bellbearer`,stages:[{key:`thief`,text:`Hunt down the Ashbound raider who stole the temple bell's clapper.`,metric:`totalAiKills`,count:1,bossId:`ashbound-raider`},{key:`curse`,text:`The clapper is cursed — the moment you lift it, it wants to ring. How will you carry it?`,metric:`totalAiKills`,count:0,choice:{prompt:`“Whatever you do — do not let it finish the sound. A bell that rings once will ring forever.”`,options:[{key:`raw`,label:`Carry it raw`,blurb:`Faster, but the Bell-Wraith wakes ENRAGED. A harder finish — and a bonus fate shard for the nerve.`,bossStatBonus:4,bonusFateShards:1,standing:`bell-raw`},{key:`cleanse`,label:`Cleanse it first`,blurb:`Spend the time to still the curse. The guardian wakes weaker. Base reward.`,standing:`bell-cleansed`}]}},{key:`carry`,text:`Carry the clapper to Yuki's ruined temple — scout 4 sectors before the bell finishes its sound.`,metric:`totalTilesExplored`,count:4,timer:{durationMs:1800*1e3,failResetToStage:2}},{key:`wraith`,text:`Re-hang the clapper and put down the temple's sealed guardian, the Bell-Wraith.`,metric:`totalAiKills`,count:1,bossId:`bell-wraith`}]},"qb-caravan":{id:`qb-caravan`,title:`The Hollow Caravan`,giver:`Caravan-master Doteki`,bandMin:12,bandMax:35,weight:7,fateShards:0,award:`Caravan's Shield`,stages:[{key:`trail`,text:`Track Doteki's vanished caravan across three sectors — follow the worsening signs.`,metric:`totalTilesExplored`,count:3},{key:`ambush`,text:`Survive the ambush at the wreck — three escalating bandit waves led by Captain Goro.`,metric:`totalAiKills`,count:3,bossId:`bandit-captain-goro`},{key:`judgment`,text:`Goro kneels, broken — and you realize he fought like a puppet on strings. What now?`,metric:`totalAiKills`,count:0,choice:{prompt:`Goro was driven against his will. His fate is yours to decide.`,options:[{key:`spare`,label:`Spare Goro`,blurb:`He was a puppet. He'll remember the mercy and walk your roads as a friend. (+standing)`,standing:`goro-spared`},{key:`execute`,label:`Execute Goro`,blurb:`Justice — and a heavier purse, taken now. The wilds grow colder toward you. (−standing)`,bonusRyoPct:50,standing:`goro-executed`}]}},{key:`strings`,text:`Cut the strings: defeat the genjutsu puppeteer Itoguchi who drove the captain.`,metric:`totalAiKills`,count:1,bossId:`puppeteer-itoguchi`}]},"qb-defector":{id:`qb-defector`,title:`The Frostfang Defector`,giver:`The Defector`,bandMin:40,bandMax:65,weight:9,fateShards:1,award:`Frostfang Survivor`,requiresWar:!0,stages:[{key:`offer`,text:`A defector from the enemy village offers war-turning intel — for safe passage. What do you do?`,metric:`totalAiKills`,count:0,choice:{prompt:`“Get me out and the war is yours. Or turn me in for your Kage's coin. Choose — they're already hunting me.”`,options:[{key:`trust`,label:`Trust the defector`,blurb:`Escort them out. Their intel feeds your village's war effort. Earns the title Border-Walker.`,title:`Border-Walker`,standing:`defector-trusted`},{key:`turnin`,label:`Turn them in`,blurb:`A bounty from your Kage — and the enmity of every sympathizer. +ryo, the title Kage's Blade.`,title:`Kage's Blade`,bonusRyoPct:40,standing:`defector-turned`}]}},{key:`silencer`,text:`Either way, an elite Hunter-Nin — Shirakawa — is sent to erase the defector, and now you. End them.`,metric:`totalAiKills`,count:1,bossId:`hunter-shirakawa`}]},"qb-gauntlet":{id:`qb-gauntlet`,title:`The Coliseum Gauntlet`,giver:`Tamer Tomoe`,bandMin:1,bandMax:100,weight:9,fateShards:1,award:`Beast-Crowned`,stages:[{key:`gauntlet`,text:`Win three coliseum pet duels against Tomoe's wandering beasts.`,metric:`totalPetWins`,count:3},{key:`stormhound`,text:`Face the finale — Raijū, the Storm-Hound — and win a pet duel.`,metric:`totalPetWins`,count:1,bossId:`raiju-storm-hound`}]},"qb-debt":{id:`qb-debt`,title:`The Gambler's Debt`,giver:`Saji Two-Coins`,bandMin:1,bandMax:100,weight:5,fateShards:0,award:`House Breaker`,stages:[{key:`table`,text:`Saji owes 'The House'. Buy him time — win two rounds of Shinobi Card Clash against the patron's enforcers.`,metric:`cardClashWins`,count:2},{key:`collection`,text:`The House calls the debt anyway and sends its bodyguard, Kuroban, to collect it from Saji's hide — and yours.`,metric:`totalAiKills`,count:1,bossId:`house-kuroban`}]},"qb-ashes":{id:`qb-ashes`,title:`Ashes of the Ashbound`,giver:`Old Hermit Roku`,bandMin:50,bandMax:100,weight:12,fateShards:1,award:`Ash-Ender`,requiresRivalry:!0,clearsRivalry:!0,stages:[{key:`cinder`,text:`Burn down Kazan's promoted lieutenant Cinder, a glass-cannon firebrand, in a volcano sector.`,metric:`totalAiKills`,count:1,bossId:`ashbound-cinder`},{key:`slag`,text:`Break Slag, the stone wall who guards the lair road.`,metric:`totalAiKills`,count:1,bossId:`ashbound-slag`},{key:`kazan`,text:`End it. Kazan the Ashbound, in his promoted form, waits in the lair. Settle the rivalry for good.`,metric:`totalAiKills`,count:1,bossId:`kazan-ashbound`}]}},r={"ashbound-raider":{name:`Ashbound Raider`,icon:`🔥`,statBonus:2,loadoutId:`bruiser`,levelOffset:1,portraitKey:`bandit2`},"bell-wraith":{name:`The Bell-Wraith`,icon:`👻`,statBonus:6,loadoutId:`boss`,levelOffset:2,portraitKey:`boss`,boss:!0},"bandit-captain-goro":{name:`Bandit Captain Goro`,icon:`🥷`,statBonus:3,loadoutId:`bruiser`,levelOffset:1,portraitKey:`bandit3`},"puppeteer-itoguchi":{name:`Itoguchi, the Hand`,icon:`🎭`,statBonus:5,loadoutId:`boss`,levelOffset:2,portraitKey:`nemesis`,boss:!0},"raiju-storm-hound":{name:`Raijū, the Storm-Hound`,icon:`⚡`,statBonus:4,loadoutId:`boss`,levelOffset:2,portraitKey:`beast`,boss:!0},"hunter-shirakawa":{name:`Hunter-Nin Shirakawa`,icon:`🥷`,statBonus:6,loadoutId:`burst`,levelOffset:2,portraitKey:`nemesis`,boss:!0},"house-kuroban":{name:`Kuroban, the Bodyguard`,icon:`🗡️`,statBonus:4,loadoutId:`bruiser`,levelOffset:1,portraitKey:`boss`,boss:!0},"ashbound-cinder":{name:`Cinder`,icon:`🔥`,statBonus:3,loadoutId:`burst`,levelOffset:0,portraitKey:`bandit2`},"ashbound-slag":{name:`Slag`,icon:`🪨`,statBonus:4,loadoutId:`defender`,levelOffset:0,portraitKey:`bandit3`},"kazan-ashbound":{name:`Kazan the Ashbound`,icon:`🌋`,statBonus:8,loadoutId:`boss`,levelOffset:3,portraitKey:`boss`,boss:!0,scalesWithRivalry:!0}};function i(e){return!e||!Object.prototype.hasOwnProperty.call(n,e)?null:n[e]}function a(e,t){let n=i(e);if(!n)return null;let r=Math.floor(Number(t)||0);return r>=0&&r<n.stages.length?n.stages[r]:null}function o(e,t,r){let i=Math.floor(Number(t)||1),a=!!r?.atWar,o=!!r?.hasRivalry,s=Object.values(n).filter(e=>i>=e.bandMin&&i<=e.bandMax&&(!e.requiresWar||a)&&(!e.requiresRivalry||o));if(s.length===0)return null;let c=0;for(let t=0;t<e.length;t++)c=Math.imul(c,31)+e.charCodeAt(t)>>>0;return s[c%s.length]}function s(e){switch(e){case`totalPetWins`:return`pet duels won`;case`cardClashWins`:return`card rounds won`;case`totalTilesExplored`:return`sectors scouted`;default:return`foes defeated`}}function c(e,t){let n=i(e);if(!n||!t)return 0;let r=0;for(let e of n.stages){if(!e.choice)continue;let n=e.choice.options.find(n=>n.key===t[e.key]);n?.bossStatBonus&&(r+=n.bossStatBonus)}return r}function l(e){let t=Math.max(0,Math.floor(Number(e)||0));return{level:Math.min(12,t*2),stat:Math.min(8,t*2)}}function u(e,t){if(!e)return null;let n=e-t;if(n<=0)return`0:00`;let r=Math.floor(n/1e3),i=Math.floor(r/60),a=r%60;return`${i}:${String(a).padStart(2,`0`)}`}var d=[{id:`rift-legacy-echo`,slug:`legacy-echo`,giverName:`Senna Graveward`,giverArchetype:`pilgrim`,levelReq:12,floors:1,theme:`legacy-echo`,landmark:`forgotten-shrine`,bossAiId:`rift-boss-legacy-echo`,bossName:`The Unremembered`,reward:{weight:5,fateShards:1,boneCharms:8},intro:[{title:`A Pilgrim on the Low Road`,scene:`Dusk on a low country road lined with small leaning gravestones. A hooded pilgrim kneels among them, brushing moss from a nameless marker, a walking staff resting across their knees.`,speaker:`Senna Graveward`,dialogue:[`I keep the graves that no one else remembers, and I have walked this low road longer than I can rightly say.`,`Most travelers pass these stones without a glance, yet you slowed, and every battle and every choice you have made has already carved something into your spirit.`,`A shape has formed behind your footsteps, and though it is faint and far from finished, one day someone with the eyes to see will know it and call it by its name.`]},{title:`What a Legacy Truly Is`,scene:`The pilgrim sits back on her heels among the leaning stones, resting her staff across her knees as if the question deserves her full attention.`,speaker:`Senna Graveward`,dialogue:[`You turned the word Legacy over just now, I saw it cross your face, so let me tell it true, since half the roads lie about it.`,`It is never bought, never gifted, and never carried in your blood. It is earned the slow way, by the fights you choose and the mercy you keep or spend, until your whole life has pressed one stubborn shape into the world.`,`You are too young to hold one yet. Grow to near your fiftieth level of strength, and a quiet old traveler will find you, name the shape your deeds have made, and offer you the paths your living has opened. You take a single one, it is yours for good, and it deepens as you prove it.`]},{title:`The Cracked Shrine`,scene:`The pilgrim rises and points with a weathered hand toward a dark ridge on the horizon, where a faint violet shimmer bleeds up from a broken shrine among the far hills.`,speaker:`Senna Graveward`,dialogue:[`There is a strange energy stirring in %sector, where an old shrine has leaned forgotten since before the first maps were drawn.`,`It is the grave of one of the Withheld, a soul of the Sunken Court who refused to surrender one small, stubborn piece of themselves, and the years wore their name away to nothing.`,`The Gate has cracked the stone and is trying to counterfeit that refusal and wear a legend it never earned, and I would ask you to go down and remember the true one, so that a name lost long ago might begin to be spoken again.`],choices:[{text:`I will go down and remember the true one.`,accept:!0},{text:`Not today. I am not ready for this.`,conclusion:`There is no shame in walking away, for the road keeps its own patience and so do I. Come find me when your footsteps turn this way again, and the stones will still be here.`}]}],descent:[{title:`Down the Short Gate`,scene:`A narrow stair of worn stone spirals down into a dim, humming hollow beneath the cracked shrine floor, a single leaning grave marker glowing faintly at the bottom.`,speaker:`Narrator`,dialogue:[`The rift opens like a wound in the shrine floor, and the stairs down are shorter than you feared, worn smooth by feet that walked here ages ago.`,`You understand, without being told, that a Legacy is not a thing of blood but a shape a life leaves behind, a pattern of deeds that outlasts the one who made it.`,`Its first keepers were erased so wholly that even their names decayed into silence, and yet the world has begun to gather its legends into one remembered hall, so that shape by buried shape those names are being spoken aloud again.`]},{title:`The Unremembered`,scene:`At the bottom of the short gate a figure waits in the grey light, its features blurred and shifting as though it can never quite decide whose face to wear. Where its heart should be, a single warm ember of someone else's refusal still burns.`,speaker:`The Unremembered`,dialogue:[`I had a name once, I am almost certain of it, and I have searched for it in every face and every grave until my own edges wore away to nothing.`,`So I have taken this bright and borrowed shape instead, this warm thing that hums inside me, and I mean to wear it and be someone at last, even though it was never mine to hold.`,`Do not pity me and do not spare me, little shinobi, for a stolen name is still a name, and I would sooner be a lie that is remembered than a truth that no one ever was.`],choices:[{text:`Rest now. I will carry the true name back into the light where it belongs.`,descend:!0},{text:`Not yet. I need to steady myself before I face this.`,conclusion:`You draw back from the seam of cold light, and the hollow voice fades behind you without anger, as patient and lost as it has always been.`},{text:`Leave this name to its rest. It is not mine to carry.`,abandon:!0,conclusion:`You turn from the cold seam and let the borrowed shape keep its quiet. Somewhere on the low road, Senna sets another nameless stone straight and says nothing.`}]}]},{id:`rift-hollow-stalker`,slug:`hollow-stalker`,giverName:`Scout Vessa`,giverArchetype:`tracker`,levelReq:30,floors:2,theme:`shadow-echo`,landmark:`hollow-rift`,bossAiId:`rift-boss-hollow-stalker`,bossName:`Hollow Stalker`,reward:{weight:8,fateShards:1,boneCharms:15},intro:[{title:`A Scout Off Her Route`,scene:`The road, a scout catching her breath against a boundary stone`,speaker:`Scout Vessa`,dialogue:[`Vessa is bent over her own knees, map still clutched in one fist, and she is not a person who bends over easily.`,`There is a tear out there. A seam in the air, the color of a bruise, and it hums like the Hollow Gate hums, but there is no gate for a hundred miles.`,`Something came out of it while I watched. Long. Wrong-jointed. It went back in before I could count its legs, and I did not want to.`]},{title:`What Leaks Back`,scene:`Vessa keeps her eyes on the seam while she speaks, plain and level, the way she would name a rockslide or a bad ford.`,speaker:`Scout Vessa`,dialogue:[`The Hollow Gate is older than any village, older than the roads. It is the power grid the Sunken Court left running when that ancient civilization died, buried under the four villages and Central both, and it is the same lost people the old legacies still trace back to.`,`The villages never built it, they only settled on its four anchors and learned to feed it, and for thirty years now each has quietly poured its takings down into the grid, Stormveil's drained reasons and Ashen Leaf's futures, Frostfang's exits and Moonshadow's secrets.`,`A seam like that one is a small tear in that grid, where everything the Gate ever swallowed comes leaking back out to pool and thicken into a body, and this one tore open far out in open country where nobody was near enough to notice or knew how to make it stop.`]},{title:`The Seam Hums`,scene:`The boundary stone, the scout's map spread flat`,speaker:`Scout Vessa`,dialogue:[`It is sitting in %sector, if you can call what it does sitting. The energy is spreading. Slow, but spreading.`,`I report anomalies. I do not close them. That is above my pay and, honestly, above my nerve.`,`You have been inside the Gate and come back out. If anyone can walk into that seam and put whatever is nesting there back in the dark, it is you.`],choices:[{text:`Go investigate the seam.`,accept:!0},{text:`Not yet. Mark it on my map and I will decide.`,conclusion:`She scratches a bruise-colored circle onto your map where the seam sits, and does not pretend she is sorry you are the one going.`}]}],descent:[{title:`The Seam`,scene:`A rift mouth torn into the hillside, humming bruise-violet`,speaker:`Narrator`,dialogue:[`The air here is wrong before you see the tear. Your teeth ache. The grass leans away from it.`,`The seam hangs open like a wound that will not close, and past its edge is the same broken-torii dark as the Hollow Gate itself, only smaller, hungrier, newer.`,`Whatever went back inside is still down there. You can hear it moving.`],choices:[{text:`Descend into the rift.`,descend:!0},{text:`Step back. Come back when I am ready.`,conclusion:`You back off the lip of the seam. It does not follow. It waits, the way patient things wait, and you feel it decide to.`},{text:`Leave this rift behind. It is not mine to close.`,abandon:!0,conclusion:`You turn from the seam and walk it off your list. Somewhere a scout crosses a line through a bruise-colored circle, and the hunt is off.`}]}]},{id:`rift-beast-warren`,slug:`beast-warren`,giverName:`Houndmaster Bel`,giverArchetype:`tracker`,levelReq:40,floors:2,theme:`beast-den`,landmark:`rift-beast-den`,bossAiId:`rift-boss-warren-alpha`,bossName:`Warren Alpha`,reward:{weight:9,fateShards:1,boneCharms:20},intro:[{title:`The Handler at the Kennels`,scene:`A kennel-yard off the road, chains rattling in empty runs`,speaker:`Houndmaster Bel`,dialogue:[`Bel keeps a hand flat against the fence rail, the way you calm a spooked animal, except the yard behind her is empty and it is her own hand shaking.`,`My pack went wrong three nights ago. Every companion I have raised, gentle beasts, family beasts, and they all turned their heads the same way at the same moment and would not turn back.`,`They ran for the ridge, toward a tear in the air that smells like the Hollow Gate and hungers like nothing I have ever fed.`]},{title:`What the Bond Is`,scene:`The kennel-yard at dusk, straw and iron and the low sound of animals settling. Bel loops an empty lead back over its peg and turns to face you, her voice dropping to the low even tone she saves for frightened animals.`,speaker:`Houndmaster Bel`,dialogue:[`A companion is not a weapon you draw and put away, it is a beast you raise from a pup, and it fights at your side because it trusts you and not because you own it.`,`That trust is the whole of the bond, there is no leash holding it in place, and a beast that loves you will step in front of the blow meant for you every time without being told.`,`The rift carries a hunger that crawls into an animal and takes hold of it from the inside, and once that hunger has the reins the trust counts for nothing, so the gentlest companion you ever raised will turn its teeth on you.`]},{title:`The Alpha Turned`,scene:`The kennel gate, a single broken collar in Bel's hands`,speaker:`Houndmaster Bel`,dialogue:[`It is nesting in %sector. The seam is pulling beast-hunger out of the ground and pouring it into whatever is closest, and what was closest was my alpha.`,`She is not my alpha anymore. She is the warren's now, a thing that calls more beasts the longer it breathes, and it will not stop calling until someone ends it.`,`You keep companions. You know the difference between a beast and a beast being ridden. Go down and give her the mercy I cannot walk in there to give.`],choices:[{text:`Go end the Warren Alpha.`,accept:!0},{text:`Not yet. Let me ready my own companions first.`,conclusion:`Bel nods hard, grateful for the honesty. Ready them well, she says. Whatever is down there was ready a long time ago.`}]}],descent:[{title:`The Warren`,scene:`A beast-den torn open under the ridge, bones and broken collars underfoot`,speaker:`Narrator`,dialogue:[`The rift here breathes warm and rank, like the inside of something living. Old collars hang from the roots. Some of them are small.`,`Deeper in, a sound that is almost a pack and almost a single throat, calling and calling, and the beast-hunger in the air answers it back.`,`The Warren Alpha waits at the center, too many shapes moving under one hide.`],choices:[{text:`Descend into the warren.`,descend:!0},{text:`Step back. Come back when I am ready.`,conclusion:`You back off. The calling does not stop. It never stops. It only gets one voice louder.`},{text:`Leave this rift behind. It is not mine to close.`,abandon:!0,conclusion:`You turn from the den. Somewhere Bel unhooks a lead from a peg and hangs it back up, and does not say the thing she wanted to say.`}]}]},{id:`rift-engine-echo`,slug:`engine-echo`,giverName:`Recorder Sann`,giverArchetype:`official`,levelReq:52,floors:3,theme:`machine`,landmark:`rift-machine`,bossAiId:`rift-boss-engine-echo`,bossName:`Engine-Echo`,reward:{weight:11,fateShards:2,boneCharms:25},intro:[{title:`The Recorder With the Wrong Ledger`,scene:`A storm-country waystation, a clerk hunched over a book that keeps writing itself`,speaker:`Recorder Sann`,dialogue:[`Sann has a clerk's steady hands and a clerk's steady face, and both are failing him at once, which is how you know it is real.`,`You know the drain. The old Engine took reasons out of Stormveil, priced them, and shipped them down it to the Hollow Gate, every manifest stamped with a quartered circle. I copied the manifests for years and told myself copying was not the same as carrying.`,`A tear has opened over the Engine's old drain-line, and it is not taking reasons in. It is bleeding them back out, all the milked grief of this village at once, and the grief has learned to stand up and walk.`]},{title:`What the Engine Drank`,scene:`The disused Engine yard behind Stormveil's arena. Sann sets a lantern on the cracked intake floor, and the old drain-seams under the chalk ring catch the light like the veins of something asleep.`,speaker:`Recorder Sann`,dialogue:[`You have stood on this arena floor and thought it only soaked up sweat and blood, but the Engine underneath it was built to drink something quieter, the reason each fighter carried in with them.`,`A reason is the plainest thing in the world, for it is the grief that will not let you sit still and the cause that makes a tired person stand back up one more time, and the Engine pulled that clean out of people at the peak of a bout and shipped it down the lower drain, the one stamped with a quartered circle, to the Gate that runs beneath all four villages.`,`The winners went home with the purse and no memory of why they had ever cared enough to bleed, and I entered every one of those hollowed men in a tidy column and stamped the result fair.`]},{title:`The Circle on the Stone`,scene:`The waystation table, a manifest weighted flat by a storm-glass paperweight`,speaker:`Recorder Sann`,dialogue:[`It is in %sector, right over the drain-line, and the quartered circle is scorched into the stone beside it, fresh, like a bill that was never paid.`,`The thing wearing all those stolen reasons calls itself nothing, but the Engine made it, so I call it the Engine-Echo. It is every closure bout and every legacy grudge this village ever sold, given one body.`,`I only ever copied the ledger. You have been inside the Gate. Go put the Engine's debt back in the dark before it collects the whole village to pay itself off.`],choices:[{text:`Go silence the Engine-Echo.`,accept:!0},{text:`Not yet. Show me the manifests first.`,conclusion:`He turns the book toward you and lets you read a column of names he has clearly read a thousand times. When you are ready, he says. The circle will keep.`}]}],descent:[{title:`The Drain-Line`,scene:`A rift torn over an old drain channel, the quartered circle scorched beside it, storm-light bleeding up`,speaker:`Narrator`,dialogue:[`The seam here hums in the storm-country key, the exact pitch the Engine used to hum, and the quartered circle beside it is still warm to stand near.`,`Reasons pour up out of the drain like smoke that remembers being a person. They braid together the deeper you look, into shoulders, into a head, into a thing that turns toward you because you are new.`,`The Engine-Echo rises out of the village's own stolen grief. It does not hate you. It simply has a debt, and you are standing in the collection.`],choices:[{text:`Descend to the Engine-Echo.`,descend:!0},{text:`Step back. Come back when I am ready.`,conclusion:`You step off the scorched circle. The storm-hum does not change. It has been patient for a village's worth of years. It can wait for you.`},{text:`Leave this rift behind. It is not mine to close.`,abandon:!0,conclusion:`You walk it off your list. Somewhere Sann closes a book that will not stay closed, and starts copying the next column.`}]}]},{id:`rift-hollow-name`,slug:`hollow-name`,giverName:`Keeper Oru`,giverArchetype:`sage`,levelReq:62,floors:2,theme:`legacy`,landmark:`rift-legacy`,bossAiId:`rift-boss-hollow-legacy`,bossName:`The Hollowed Name`,reward:{weight:12,fateShards:2,boneCharms:30},intro:[{title:`The Keeper of the Hall-Road`,scene:`A quiet shrine-road, an old keeper reading names off a worn wooden slate`,speaker:`Keeper Oru`,dialogue:[`Oru keeps the small shrine where the road remembers the Wandering Sage's teaching, that a legacy is a thing you earn and never a thing you are simply handed, and never a thing that can be taken back once it is truly yours.`,`There was a shinobi once whose era ended badly. A legendary name, a name they carve in the Hall of Legends, and then a fall, and then the slow work of being forgotten on purpose.`,`A rift has found what is left of that name. Not the person. The person is long gone. Only the hollow shape a legacy leaves behind once its owner is dead and forgotten, the technique with no one left to mean it, and it is trying to be walked again.`]},{title:`The Hall and the Hollow`,scene:`Inside the small shrine, Oru stands before a wall of carved names lit by low lanternflame, one hand resting on the cold stone.`,speaker:`Keeper Oru`,dialogue:[`The world keeps a great record called the Hall of Legends, and beside every name it stamps the era, the age of history, in which that deed was done.`,`A legacy is a title and a signature technique you earn by how you truly lived, and once you accept it, it is sealed to you forever and can never be traded away or stripped from you.`,`What can change is a name's standing in that Hall, because a fallen legend's entry may be marked revoked or hidden with a note explaining the correction, yet even then the world annotates the record rather than erasing it.`]},{title:`An Era That Will Not End`,scene:`The shrine step, the name-slate turned face-down`,speaker:`Keeper Oru`,dialogue:[`It stands in %sector, wearing an era that already ended, swinging techniques no living hand has the right to anymore.`,`The Sage would tell you a hollow legacy is the most dangerous kind, because it fights with everything a legend earned and none of the reasons a legend stopped. I am only a keeper. I light the shrine. I do not close the wounds it warns about.`,`You have earned your own path the hard way. You will understand what it means to meet a name that was earned and then hollowed. Go and let that era rest.`],choices:[{text:`Go lay the Hollowed Name to rest.`,accept:!0},{text:`Not yet. Tell me whose name it was.`,conclusion:`Oru turns the slate over, reads a name aloud once, and turns it back down. That much it earned, he says. The rest it lost. Come back when you are ready to give it the ending.`}]}],descent:[{title:`The Hollowed Legacy`,scene:`A rift like an old shrine turned inside out, era-banners rotted to threads`,speaker:`Narrator`,dialogue:[`The seam here is quiet where the others roared, reverent, the way a tomb is reverent. That is worse.`,`Banners of an ended era hang in the dark, rotted to cobweb, and beneath them a figure practices a form, alone, perfect, forever, the way only a hollow thing can be perfect.`,`The Hollowed Name turns to face you with a legend's poise and nothing at all behind the eyes. It remembers every technique. It has forgotten every reason. It will fight you the way a name fights when it refuses to end.`],choices:[{text:`Descend to the Hollowed Name.`,descend:!0},{text:`Step back. Come back when I am ready.`,conclusion:`You leave the reverent dark. The figure does not stop its form. It has practiced through longer absences than yours.`},{text:`Leave this rift behind. It is not mine to close.`,abandon:!0,conclusion:`You turn away. Somewhere Oru lights the shrine lamp anyway, for a name that will not accept it is out of era.`}]}]},{id:`rift-mirror-shard`,slug:`mirror-shard`,giverName:`Broker Nemo`,giverArchetype:`broker`,levelReq:70,floors:3,theme:`mirror`,landmark:`rift-machine`,bossAiId:`rift-boss-mirror-shard`,bossName:`Mirror-Shard Warden`,reward:{weight:13,fateShards:3,boneCharms:35},intro:[{title:`The Broker Who Sells Nothing Tonight`,scene:`A moonlit canal booth, its shelf of sealed files knocked to the floor`,speaker:`Broker Nemo`,dialogue:[`Nemo is a Moonshadow broker, which means he sells secrets for a living, and tonight he is not selling, which for his kind is a kind of terror.`,`You know the Mirror. The machine under Moonshadow took surrendered trust, names and files and confessions, and piped them down to the Hollow Gate, every reading stamped with a quartered circle.`,`A rift has cracked open a shard of the Mirror, and the shard is doing what the Mirror always did, only loose. It is putting on stolen faces. It walked past me wearing mine.`]},{title:`What the Mirror Drank`,scene:`The canal booth. Nemo keeps one hand flat on a shuttered whisper-booth's cold glass as if holding a door shut, his eyes on the faint quartered mark scored into its frame.`,speaker:`Broker Nemo`,dialogue:[`The Mirror was Moonshadow's still-water basin, and every person this village ever registered had a private reading of themselves drunk straight down into it.`,`A secret is not only a whispered rumor, it is the exact moment you hand another person a name or a confession and believe they will keep you safe, and that surrendered trust is the thing the basin actually took.`,`None of it stayed here either, because each reading was stamped with a quartered circle and piped down to the Hollow Gate, and now a loose shard of that hoard is walking my streets wearing the faces those secrets belonged to.`]},{title:`A Face That Is Not Yours`,scene:`The canal booth, a broken hand-mirror reflecting the wrong room`,speaker:`Broker Nemo`,dialogue:[`It is holding in %sector, a warden made of every secret the Mirror ever swallowed, and it wears the faces of the people those secrets belonged to, one after another, none of them home.`,`I have spent my life selling other people's truths. I did not think one would ever come back wearing my mouth. I cannot fight a thing that keeps showing me people I sold.`,`You have been inside the Gate and kept your own face. Go break the shard before it learns enough faces to stop being a rift and start being a person nobody can trust.`],choices:[{text:`Go break the Mirror-Shard Warden.`,accept:!0},{text:`Not yet. Whose face was it wearing?`,conclusion:`Nemo looks at you a long moment and does not answer, which is its own answer. Come back, he says, before it wears yours.`}]}],descent:[{title:`The Shard`,scene:`A rift of black glass and moonlight, reflections that move a half-beat late`,speaker:`Narrator`,dialogue:[`The seam here is a wound of mirror, and every surface shows you a room you are not standing in and a face you are not wearing.`,`At the center a warden turns, and its face is a shard of the Mirror, and across it faces run like water, borrowed, surrendered, sold. For one beat it wears yours, and gets it slightly wrong.`,`The Mirror-Shard Warden is every secret Moonshadow ever gave away, standing up and asking to be sold one more time.`],choices:[{text:`Descend to the shard.`,descend:!0},{text:`Step back. Come back when I am ready.`,conclusion:`You step back from the glass. Your reflection stays a half-beat, watching you go, before it agrees to leave too.`},{text:`Leave this rift behind. It is not mine to close.`,abandon:!0,conclusion:`You walk it off your list. Somewhere Nemo picks his sealed files up off the floor, and does not check whether they are still his.`}]}]},{id:`rift-gate-heir`,slug:`gate-heir`,giverName:`Kite Harrow`,giverArchetype:`broker`,levelReq:80,floors:3,theme:`gate`,landmark:`rift-gate`,bossAiId:`rift-boss-gate-heir`,bossName:`Hollow Gate Heir`,reward:{weight:15,fateShards:3,boneCharms:45},intro:[{title:`The Unsworn on the Ridge`,scene:`A high ridge, Kite Harrow on a wagon's tailboard reading a contract she has already read`,speaker:`Kite Harrow`,dialogue:[`Kite Harrow is where the roads run out, unsworn as ever, no village mark on her and a ledger on her knee that names things no village will admit are named.`,`You have closed the little tears. The stalker, the warren, the echoes. I have been keeping the receipts. Congratulations, you gave the Hollow Gate indigestion.`,`This one is not a leak. The Engine, the Rootfire, the Vault, the Mirror, all four villages' tribute has been backing up the quartered-circle drain at once, and it has to go somewhere, and somewhere grew a body.`]},{title:`What the Rifts Were Really About`,scene:`The tailboard. Harrow taps a folded ledger against her knee and lets out a dry breath, done with riddles, ready to say the plain thing out loud.`,speaker:`Kite Harrow`,dialogue:[`Four villages, four machines, and every one of them quietly robs its own people: Stormveil's Engine drinks the reason a fighter ever picked up the knife, Ashen Leaf's Rootfire burns the life a child was going to grow into, Frostfang's Vault buys the moment you would have walked away and did not, and Moonshadow's Mirror swallows the trust you handed the person who swore they would keep you safe.`,`None of that stays up here, because each machine leaves the locals a comforting little share on top and pipes the real surplus down one hidden lower pipe stamped with a circle cut in four quarters, a quarter for each village, straight into the buried thing they all feed and none of them will name.`,`That buried thing is the Hollow Gate, and no village built it, it is the still-running power grid of the Sunken Court, the same ancient people your own legacy will one day trace back to. The four villages are only refugees who settled on its anchors and have fed it for thirty years, and the Heir you are walking toward is every last bit of that hoard forcing its way back out through one living body at once.`]},{title:`An Heir to the Gate`,scene:`The tailboard, four village seals laid out in a row on the wood`,speaker:`Kite Harrow`,dialogue:[`It is nesting in %sector, and it is the closest thing to the Hollow Gate itself that anyone unsworn has ever stood next to and lived. An heir. Reasons and futures and exits and secrets, all four, wearing one shape.`,`I do not do this for villages. No village owns my silence and no village will move on a thing that owes every seat a favor. So this is a contract on no roll. Not Central's, not any Kage's. Mine, and now yours.`,`Go down and put the heir back where the Gate keeps the rest of what it stole. I will nail what you find to a waystation board where all four villages have to read it at once. I always keep the receipt.`],choices:[{text:`Take the contract. Face the Hollow Gate Heir.`,accept:!0},{text:`Not yet. Tell me who you are really protecting.`,conclusion:`Myself, she says, without a flicker. And everyone the Gate would eat next if it got an heir that lived. She lets you decide which order to believe those in, and waits.`}]}],descent:[{title:`The Heir`,scene:`The deepest rift yet, four-fold, storm and root and ice and moonlight braided into one dark throat`,speaker:`Narrator`,dialogue:[`The seam here is not one color. It is four, quartered like the circle itself, storm and root-fire and vault-ice and mirror-moon bleeding into a single dark that goes down further than a hillside should allow.`,`Everything the four machines ever drained is here at once, and it has agreed on a shape. It has taken reasons for a spine, futures for hands, exits for the legs it walks toward you on, and secrets for the face it has not yet decided to show.`,`The Hollow Gate Heir stands where all four villages' debts collect. It is the nearest thing to the Gate you will ever fight and walk away from, if you walk away.`],choices:[{text:`Descend to the Hollow Gate Heir.`,descend:!0},{text:`Step back. Come back when I am ready.`,conclusion:`You step off the four-fold lip. The dark does not lunge. It has four villages' worth of patience, and it counts you as already owed.`},{text:`Leave this rift behind. It is not mine to close.`,abandon:!0,conclusion:`You turn from the throat of it. Somewhere Harrow draws a single clean line through an entry in her ledger, and writes a smaller word beside it: later.`}]}]}];function f(e){return d.find(t=>t.id===e)??null}var p=`rift-giver-`,m=`__rift-accept`,h=`__rift-descend`,g=`__rift-abandon`,_={tracker:`tracker`,pilgrim:`pilgrim`,courier:`courier`,soldier:`patrol`,sage:`sage`,broker:`bountyHunter`,official:`patrol`},v={tracker:`wanderer-tracker`,pilgrim:`wanderer-pilgrim`,courier:`wanderer-courier`,soldier:`wanderer-patrol`,sage:`wanderer-sage`,broker:`wanderer-bounty-hunter`,official:`wanderer-patrol`};function y(e){return`/portraits/${v[e.giverArchetype]}.webp`}function b(e){return`/portraits/${e.bossAiId}.webp`}function x(e,t){let n=t.trim().toLowerCase();if(n===e.giverName.trim().toLowerCase())return y(e);if(n===e.bossName.trim().toLowerCase())return b(e)}function S(e,t){let n=2166136261,r=`${e}|${t}`;for(let e=0;e<r.length;e++)n^=r.charCodeAt(e),n=Math.imul(n,16777619);let i=new Set([11,31,38,47]),a=Math.abs(n)%55+1;for(let e=0;e<60&&i.has(a);e++)a=a%55+1;return a}function C(e){if(e.activeRiftQuest||Date.now()<(e.riftCooldownUntil??0))return null;let t=d.filter(t=>e.level>=t.levelReq);if(!t.length)return null;let n=Math.floor(Date.now()/(1440*60*1e3)),r=2166136261,i=`${e.name}|${n}`;for(let e=0;e<i.length;e++)r^=i.charCodeAt(e),r=Math.imul(r,16777619);let a=[...t].sort((e,t)=>t.levelReq-e.levelReq),o=a.map((e,t)=>.5**t),s=o.reduce((e,t)=>e+t,0),c=Math.abs(r)%1e6/1e6*s;for(let e=0;e<a.length;e++)if(c-=o[e],c<0)return a[e];return a[a.length-1]}function w(e,t){let n=0;for(let t of e.slug)n=n*31+t.charCodeAt(0)>>>0;let r=60+(t*7+n)%8+2,i=_[e.giverArchetype];return{id:`${p}${e.slug}`,name:e.giverName,archetype:i,verb:`quest`,level:e.levelReq,homeTile:r,waypoints:[r,r+1,r-1],greeting:`${e.giverName} flags you down, still shaken by whatever they saw.`,tellTint:`#a855f7`,avatarKey:i}}function T(e){return e.startsWith(`rift-giver-`)?f(`rift-${e.slice(11)}`):null}function E(n){let r=t(n);return`${r?`the outskirts of ${r}`:e(n)} (sector ${n})`}function D(e,t,n){return e.map((e,r)=>({title:e.title,scene:e.scene,speaker:e.speaker,rightImage:n(e.speaker),dialogue:e.dialogue,choices:r===t?e.choices?.map(e=>({text:e.text,nextPage:t,conclusion:e.conclusion,trait:e.accept?m:e.descend?h:e.abandon?g:void 0})):void 0}))}function O(e,t,n){let r=E(t),i=D(e.intro.map(e=>({...e,dialogue:e.dialogue.map(e=>e.replace(/%sector/g,r))})),e.intro.length-1,t=>x(e,t));return{id:`${p}${e.slug}`,name:`Strange Energy: ${e.bossName}`,biome:n,icon:`🌀`,eventKind:`visualNovel`,trigger:`manual`,vnTitle:e.intro[0]?.title??`Strange Energy`,vnScene:e.intro[0]?.scene??``,vnSpeaker:e.intro[0]?.speaker??e.giverName,image:`/scenes/story/${p}${e.slug}.webp`,vnPages:i,levelReq:e.levelReq,xpReward:0,ryoReward:0,staminaReward:0,dialogue:e.intro.flatMap(e=>e.dialogue)}}function k(e,t){let n=D(e.descent,e.descent.length-1,t=>x(e,t));return{id:`rift-descend-${e.slug}`,name:`The Rift: ${e.bossName}`,biome:t,icon:`🌀`,eventKind:`visualNovel`,trigger:`manual`,vnTitle:e.descent[0]?.title??`The Rift`,vnScene:e.descent[0]?.scene??``,vnSpeaker:e.descent[0]?.speaker??`Narrator`,image:`/scenes/story/rift-descend-${e.slug}.webp`,vnPages:n,levelReq:e.levelReq,xpReward:0,ryoReward:0,staminaReward:0,dialogue:e.descent.flatMap(e=>e.dialogue)}}function A(e){return e.startsWith(`rift-descend-`)}function j(e){return e.startsWith(`rift-descend-`)?f(`rift-${e.slice(13)}`):null}export{u as S,o as _,A as a,a as b,T as c,S as d,E as f,c as g,r as h,p as i,k as l,f as m,m as n,C as o,w as p,h as r,j as s,g as t,O as u,s as v,l as x,i as y};